INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770346830655, 'Speakers', 'S2-W12D2', '12" Subwoofer with Dual 2 Ohm', '장착 공임 별도/20만원 부터', 500000, 'assets/images/spk-S2W12.jpg', '[{"id":1770346918079.5222,"type":"text","value":"FEATURES\nDual Voice Coil Subwoofers with Configuration Jumpers\nCarbon Fiber / Poly Propylene Cone\nPoly Propylene / Ceramic Dust Cap\nHigh-Grade Strontium Ferrite Magnets\nTwist-Lock Grille Mount System\nHigh-Amplitude Multi-Roll (H.A.M.R.) Surround\nPush-Type Speaker Terminals (Up to 8AWG Wire Size)\n\nTECH SPECS\nPower Handling: RMS 600W / 1800W Peak\nNominal Impedance: 2 Ohm\nFrequency Response: 23Hz - 215Hz\nSensitivity (1W/1M): 82.7dB\nVoice Coil: 1.4\"\nX-Max (1-Way): 13mm\n\nMagnet Weight: 34oz"},{"id":1770347076677.2585,"type":"text","value":"놀라운 성능의 S-시리즈 S2-W12D2 12인치 서브우퍼로 당신의 카 오디오 시스템을 한 단계 업그레이드해 보세요. 이 특별한 제품은 완전히 새로운 설계를 통해, 이전에는 고가 모델에서나 기대할 수 있었던 강력한 베이스 파워와 신뢰성을 선사합니다.\n\n주요 특징 및 성능\n압도적인 공기 흐름: 정밀하게 제작된 12인치 드라이버는 엄청난 양의 공기 흐름을 만들어냅니다. 단순히 공간을 울리는 소리를 넘어, 온몸으로 느껴지는 깊고 묵직한 베이스를 경험할 수 있습니다.\n\n정밀 공학 설계: 듀얼 2옴(2-ohm) 보이스 코일은 세밀한 사양에 맞춰 전문적으로 감겨 있습니다. 이는 서브우퍼의 효율을 최적화하고 시간이 지나도 일관되고 신뢰할 수 있는 성능을 보장합니다.\n\n강력한 내구성: 재설계 과정에서 내구성에 큰 중점을 두었습니다. 견고한 구조와 고품질 부품은 가혹한 사용 환경에서도 견딜 수 있도록 제작되어 오랫동안 변함없는 감동을 전달합니다.\n\n편의성 및 가치\n뛰어난 범용성: 유연한 연결 옵션을 갖추고 있어 다양한 커스텀 카 오디오 구성에 쉽고 매끄럽게 통합됩니다.\n\n합리적인 접근성: S2-W12D2의 가장 큰 매력은 놀라운 가성비입니다. 큰 비용 부담 없이도 프리미엄급 베이스 성능과 신뢰성을 누릴 수 있어, 누구나 오디오 시스템의 수준을 높일 수 있습니다."},{"id":1770349107209.4373,"type":"image","value":"assets/images/spk-S2W01.jpg"},{"id":1770349121083.3032,"type":"text","value":"성능 및 가치\n\n탁월한 출력 성능: 정격 출력(RMS) 600W와 최대 출력(Peak) 1800W라는 인상적인 전력 처리 능력을 갖춘 차세대 10인치 S-시리즈 서브우퍼는 탁월한 성능 가치를 선사합니다.\n\n정교한 베이스 재생: 25Hz에서 215Hz에 이르는 넓은 주파수 응답 범위와 82.7dB(1W/1m)의 감도를 자랑하는 이 서브우퍼들은 다양한 음악 장르에 걸쳐 강력하고 정확한 베이스 재생을 보장합니다."},{"id":1770349139027.7427,"type":"image","value":"assets/images/spk-S2W-02.jpg"},{"id":1770349152749.891,"type":"text","value":"HAMR 서라운드 (H.A.M.R. Surround)\n\n차세대 S-시리즈 서브우퍼에는 Alpine의 HAMR(고진폭 멀티롤) 서라운드 기술이 탑재되어 있습니다.\n\n효율적인 공기 이동 및 냉각: 특수 고무 서라운드 설계 덕분에 서브우퍼 콘이 과열되지 않으면서도 공기를 효율적으로 이동시킬 수 있습니다.\n\n놀라운 정확도: 이 기술은 **15mm의 한 방향 진폭(One-way excursion)**을 가능하게 하여, 서브우퍼에서 뿜어져 나오는 베이스의 정확도를 극대화합니다."},{"id":1770349153739.1475,"type":"image","value":"assets/images/spk-S2W-03.jpg"},{"id":1770349166183.673,"type":"text","value":"강화된 타격감 (Enhanced Punch)\n\n차세대 S-시리즈 서브우퍼 콘은 가벼우면서도 견고한 카본 파이버(탄소 섬유)와 폴리프로필렌의 조합을 특징으로 합니다. 이를 통해 음악의 깊이와 풍부함을 더해주는, 왜곡이 적고 깊은 베이스를 선사합니다."},{"id":1770349166909.6973,"type":"image","value":"assets/images/spk-S2W-04.jpg"},{"id":1770349179273.4429,"type":"text","value":"유연한 활용성 (Flexible Application)\n\n간편한 DVC 설치: 설정이 용이한 점퍼를 갖춘 듀얼 보이스 코일(DVC) 덕분에 S-시리즈 서브우퍼를 매우 쉽고 빠르게 설치할 수 있습니다.\n\n트위스트 락 그릴 시스템: 새로운 트위스트 락(Twist-lock) 마운팅 시스템은 장착 나사 없이도 옵션 그릴을 간편하게 설치하거나 제거할 수 있게 해주며, 외부 충격으로부터 콘을 안전하게 보호합니다."}]'::jsonb, '[{"id":1770349104387,"name":"OM_S2-Subwoofers","url":"assets/files/OM_S2-Subwoofers.pdf"}]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
