INSERT INTO "alpine-home".products (id, category, title, description, desc_bottom, price, image, detail_blocks, attachments, manual_url) VALUES (1770350638022, 'Speakers', 'DPS-25M', '2.5" Midrange Speaker Set (테두리 68mm * 두께 40mm)', '장착 공임 별도/20만원 부터', 250000, 'https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DPS-25M-001.jpg', '[{"id":1770778177684.0828,"type":"text","value":"2.5inchs Full Range Speaker\n\nMax : 60W\n260Hz~20kHz\n83dB"},{"id":1772682317622.1082,"type":"image","value":"https://raw.githubusercontent.com/alpinehome-jcha/alpinehompage/main/assets/images/DPS-25M-002.jpg"},{"id":1772682331720.4426,"type":"text","value":"DPS-25M의 수입명은 DSP-65C-SIEN이지만 한국출시 명칭은 DPS-25M 입니다.\n\n2.5\" 미드레인지 스피커로, 작은사이즈의 OEM 미드레인지를 교체할때 유용합니다.\n\n카니발/스포티지/싼타페/그랜저/K8/쏘나타/K5의 센터 스피커와 미드레인지 스피커, 서라운드 스피커 교체용.\n\n제네시스 렉시콘/B&O의 후면 미드레인지 스피커와 서라운드 스피커 교체용.\n\nDPS-25M-Uni Baffle을 함께 사용하면 편리하게 장착할 수 있습니다.\n\n"}]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO NOTHING;
